SELECT COUNT(*) FROM core_record c
JOIN employment_and_income i ON c.coreregistry = i.emplcoreref
JOIN expenses_and_assets e ON i.emplcoreref = e.expemplref;

SELECT e.liqassets, e.totassets, (e.networth + e.totliabs) as nw_plus_liabs,
       CASE WHEN e.totassets = (e.networth + e.totliabs) THEN 'equal' ELSE 'not_equal' END as comparison
FROM expenses_and_assets e LIMIT 10;
